    {
      "name": "MvPowerSeries.ne_zero_iff_exists_coeff_ne_zero",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (f : MvPowerSeries σ R), f ≠ 0 ↔ ∃ d, (MvPowerSeries.coeff d) f ≠ 0"
    },
    {
      "name": "MvPolynomial.degrees_sum_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {ι : Type u_3} [inst_1 : DecidableEq σ] (s : Finset ι)\n  (f : ι → MvPolynomial σ R), (∑ i ∈ s, f i).degrees ≤ s.sup fun i => (f i).degrees"
    },
    {
      "name": "MvPolynomial.degreesLE_zero",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R], MvPolynomial.degreesLE R σ 0 = 1"
    },
    {
      "name": "MvPolynomial.degreesLE",
